<?php
 class PrettyExceptionsTest extends PHPUnit_Framework_TestCase { public function testReturnsUnchangedSuccessResponse() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/index.php', 'PATH_INFO' => '/foo' )); $app = new \Slim\Slim(); $app->get('/foo', function () { echo "Success"; }); $mw = new \Slim\Middleware\PrettyExceptions(); $mw->setApplication($app); $mw->setNextMiddleware($app); $mw->call(); $this->assertEquals(200, $app->response()->status()); $this->assertEquals('Success', $app->response()->body()); } public function testReturnsDiagnosticsForErrorResponse() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/index.php', 'PATH_INFO' => '/foo' )); $app = new \Slim\Slim(array( 'log.enabled' => false )); $app->get('/foo', function () { throw new \Exception('Test Message', 100); }); $mw = new \Slim\Middleware\PrettyExceptions(); $mw->setApplication($app); $mw->setNextMiddleware($app); $mw->call(); $this->assertEquals(1, preg_match('@Slim Application Error@', $app->response()->body())); $this->assertEquals(500, $app->response()->status()); } public function testResponseContentTypeIsOverriddenToHtml() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/index.php', 'PATH_INFO' => '/foo' )); $app = new \Slim\Slim(array( 'log.enabled' => false )); $app->get('/foo', function () use ($app) { $app->contentType('application/json;charset=utf-8'); throw new \Exception('Test Message', 100); }); $mw = new \Slim\Middleware\PrettyExceptions(); $mw->setApplication($app); $mw->setNextMiddleware($app); $mw->call(); $response = $app->response(); $this->assertEquals('text/html', $response['Content-Type']); } public function testExceptionTypeIsInResponseBody() { \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/index.php', 'PATH_INFO' => '/foo' )); $app = new \Slim\Slim(array( 'log.enabled' => false )); $app->get('/foo', function () use ($app) { throw new \LogicException('Test Message', 100); }); $mw = new \Slim\Middleware\PrettyExceptions(); $mw->setApplication($app); $mw->setNextMiddleware($app); $mw->call(); $this->assertContains('LogicException', $app->response()->body()); } public function testWithCustomLogWriter() { $this->setExpectedException('\LogicException'); \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/index.php', 'PATH_INFO' => '/foo' )); $app = new \Slim\Slim(array( 'log.enabled' => false )); $app->container->singleton('log', function () use ($app) { return new \Slim\Log(new \Slim\LogWriter('php://temp')); }); $app->get('/foo', function () use ($app) { throw new \LogicException('Test Message', 100); }); $mw = new \Slim\Middleware\PrettyExceptions(); $mw->setApplication($app); $mw->setNextMiddleware($app); $mw->call(); $this->assertContains('LogicException', $app->response()->body()); } } 